"""Natural manual Comskip in existing Fixture/Workflow; no fake executable/task.
Original Dispatcharr, Comskip and dependency authors retain all credit.
"""
import base64,hashlib,json,traceback,uuid,re,shutil
from pathlib import Path
from workflow import save
import m3u_refresh_all_cases as aggregate
import dvr_domain_cases as journal
CASE='comskip-manual'
TASK='apps.channels.tasks.comskip_process_recording'

def prepare_context(f):
 if f.case!=CASE:raise ValueError('OwnedComskipContextRequired')
 f._provider_environment=getattr(f,'_provider_environment',{})
 if f.backend=='Native':f._provider_environment['RUST_EXPERIMENTAL_SELECTED_BEAT']='0'
 f.sql("from core.models import CoreSettings;from django_celery_beat.models import PeriodicTask,PeriodicTasks;PeriodicTask.objects.all().update(enabled=False);PeriodicTasks.update_changed();s,_=CoreSettings.objects.get_or_create(key='dvr_settings',defaults={'name':'DVR Settings','value':{}});CoreSettings.objects.filter(pk=s.pk).update(value={**(s.value or {}),'comskip_enabled':False,'comskip_mode':'mark','comskip_hw_accel':'none','comskip_custom_path':''});print(json.dumps({'manual_mode':'mark','automatic_comskip':False}))")
 # Real fixture input generated by pinned Original FFmpeg. This is an imported
 # completed-file manual workflow, not acceptance of automatic DVR recording.
 guest='/shared/'+CASE+'/manual.mkv'
 script="import subprocess,os,hashlib,json;from pathlib import Path;p=Path("+repr(guest)+");p.parent.mkdir(exist_ok=True);args=['ffmpeg','-v','error','-f','lavfi','-i','testsrc2=size=320x180:rate=25','-f','lavfi','-i','sine=frequency=440:sample_rate=48000','-t','8','-c:v','libx264','-preset','ultrafast','-c:a','aac','-y',str(p)];r=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30);assert r.returncode==0 and p.is_file();os.chown(p,65532,65532);p.chmod(0o644);print(json.dumps({'actual_exit':r.returncode,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'argv':args,'stderr':r.stderr.decode()}))"
 if f.backend=='Original':f._comskip_input=json.loads(f.python(script,seconds=40,secret=True))
 else:
  ref=f.binding['retained_source_comskip']['input'];source=Path(ref['path']);assert hashlib.sha256(source.read_bytes()).hexdigest()==ref['sha256']=='ebcc185d00fb24ab467c0605639415061f3001ff09e1381a70420fd1aa72fd3d'
  target=f.case_data/'manual.mkv';assert not target.exists()
  # The case directory belongs to actual containerUID65532 (subuid onhost);
  # use the existing owned Docker copy path, then actual guest root chowns it.
  transfer=f.data/('.owned-comskip-source-input-'+uuid.uuid4().hex+'.mkv')
  assert not transfer.exists();shutil.copyfile(source,transfer);transfer.chmod(0o644)
  try:
   assert hashlib.sha256(transfer.read_bytes()).hexdigest()==ref['sha256']
   f.command([f.docker,'cp',str(transfer),f.project+'-baseline-1:'+guest],seconds=20)
  finally:transfer.unlink()
  f._comskip_input=json.loads(f.python("import os,json,hashlib;from pathlib import Path;p=Path("+repr(guest)+");os.chown(p,65532,65532);print(json.dumps({'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'generated_in_this_context':False,'actual_operation':'copy exact retained Source FFmpeg-generated fixture input'}))",secret=True))
  assert f._comskip_input['sha256']==ref['sha256']and f._comskip_input['bytes']==719267

 path=guest if f.backend=='Original'else'/data/manual.mkv'
 code="from apps.channels.models import Recording;from django.utils import timezone;from datetime import timedelta;now=timezone.now();rows=Recording.objects.bulk_create([Recording(channel_id="+str(f.channel_id)+",start_time=now-timedelta(seconds=10),end_time=now-timedelta(seconds=2),custom_properties=cp)for cp in[{'status':'completed','remux_success':True,'file_path':"+repr(path)+",'program':{'title':'Owned manual Comskip input'}},{'status':'completed','remux_success':True,'program':{'title':'Owned no-file Comskip input'}}]]);print(json.dumps({'real':rows[0].pk,'no_file':rows[1].pk}))"
 f._comskip_rows=f.sql(code,secret=True)
 f._comskip_ini=json.loads(f.python("import json;from pathlib import Path;print(json.dumps(next((p for p in ['/etc/comskip/comskip.ini','/app/docker/comskip.ini']if Path(p).exists()),None)))",secret=True))

def run(f):
 if f.case!=CASE or f.backend not in('Original','Native'):raise ValueError('OwnedComskipCharacterizationRequired')
 out=f.output/CASE;out.mkdir(exist_ok=False);private=out/'private';private.mkdir(mode=0o700)
 report={'status':'running','cases':[],'manual_completed_imported_fixture_only':True,'automatic_comskip_qualified':False,'cut_mode_qualified':False,'full_milestone_passed':False,'performance_verified':False}
 save(private/'actual-imported-input-provenance.json',f._comskip_input)
 if f.backend=='Native':
  refs=f.binding['retained_source_comskip']
  for ref in refs.values():assert hashlib.sha256(Path(ref['path']).read_bytes()).hexdigest()==ref['sha256']
  source_execution=json.loads(Path(refs['execution']['path']).read_text());assert source_execution['actual_exit']==0 and source_execution['stdout_EOF']and source_execution['stderr_EOF']and source_execution['process_group_settled']
  assert json.loads(Path(refs['report']['path']).read_text())['status']=='passed'and json.loads(Path(refs['cleanup']['path']).read_text())['exact_owned_absence']and json.loads(Path(refs['Root_cleanup']['path']).read_text())['passed']
  files=['/opt/dispatcharr-comskip/bin/comskip','/app/docker/comskip.ini','/usr/share/doc/dispatcharr/comskip-NOTICE','/usr/share/doc/dispatcharr/comskip-LICENSE'];proof=f.command([f.docker,'exec',f.native,'sha256sum',*files]);save(private/'actual-Native-packaged-comskip-hashes.json',{'actual_stdout':proof})
  actual={path:digest for digest,path in(line.split(maxsplit=1)for line in proof.splitlines())};assert actual==dict(zip(files,['1452696c945a64f5351977143ecad3d384e7036479ba5d85ed9c928d6e20d460','7614488f8addcd44850f524f5a7d104527aa6d80c25dbdf8d60219d4e658b896','8fbfca872c84833fd02682bbf190a7910b44e6ec6edd6a778ff8d6d0634d8c9d','db296f2f7f35bca3a174efb0eb392b3b17bd94b341851429a3dff411b1c2fc73']))
 observer=None
 def row(ident):return f.sql("from apps.channels.models import Recording;print(json.dumps(Recording.objects.values('id','custom_properties').get(pk="+str(ident)+")))",secret=True)
 def media():return json.loads(f.python("import json,hashlib;from pathlib import Path;p=Path('/shared/"+CASE+"/manual.mkv');e=p.with_suffix('.edl');print(json.dumps({'input_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'input_bytes':p.stat().st_size,'EDL_exists':e.exists(),'EDL_sha256':hashlib.sha256(e.read_bytes()).hexdigest()if e.exists()else None,'EDL_text':e.read_text()if e.exists()else None}))",secret=True))
 def invoke(label,ident,expected):
  nonlocal observer
  cell={'name':label,'status':'running'};report['cases'].append(cell);save(out/'report.json',report)
  try:
   f.wait(lambda:not any(aggregate.broker(f).values()),20,label+'-previous-owner-drained')
   before=row(ident);input_before=media();receiver=aggregate.receiver_begin(f,label);observer=journal.observer_start(f,label,database=1)
   response=f.api('POST','/api/channels/recordings/'+str(ident)+'/comskip/',{});save(private/(label+'-HTTP.json'),response)
   assert response['status']==200 and response['body']=={'success':True,'queued':True}
   def frame():
    frames=[r for r in aggregate.frames(observer)if r['headers']['task']==TASK];assert len(frames)<=1
    return frames[0]if frames else False
   actual=f.wait(frame,15,label+'-natural-publication');task=actual['headers']['id'];assert actual['headers']['root_id']==task and actual['headers']['parent_id']is None
   assert json.loads(base64.b64decode(actual['body']))==[[ident],{},{'callbacks':None,'errbacks':None,'chain':None,'chord':None}]
   result=f.wait(lambda:aggregate.terminal(f,task),330,label+'-actual-comskip-terminal');save(private/(label+'-backend.json'),result)
   assert result['status']=='SUCCESS'and result['result']in expected and result['children']==[]
   f.wait(lambda:not any(aggregate.broker(f).values()),20,label+'-actual-broker-drained')
   durable=journal.producer_observer_stop(f,observer);observer=None;save(private/(label+'-journal.json'),durable)
   assert [(p['task'],p['id'])for p in durable['publications']]==[(TASK,task)]
   after=row(ident);input_after=media();events=aggregate.receiver_read(f,receiver);save(private/(label+'-observations.json'),{'before':before,'after':after,'media_before':input_before,'media_after':input_after,'events':events,'frame':actual})
   assert input_before['input_sha256']==input_after['input_sha256']==f._comskip_input['sha256']
   statuses=[p['data']for p in events['events']if isinstance(p.get('data'),dict)and p['data'].get('type')=='comskip_status'and p['data'].get('recording_id')==ident]
   if label=='real-manual-mark':
    cp=after['custom_properties']['comskip'];expected_cp={'status':'completed'}
    end={'success':True,'type':'comskip_status','recording_id':ident}
    if result['result']=='ok':
     assert input_after['EDL_exists']and isinstance(cp['commercials'],int)and cp['commercials']>0
     expected_cp.update(mode='mark',edl='manual.edl',commercials=cp['commercials']);end.update(status='completed',commercials=cp['commercials'],mode='mark')
    else:
     expected_cp['skipped']=True;end.update(status='skipped',reason='no_commercials_detected')
     if 'edl'in cp:expected_cp['edl']='manual.edl';end.update(reason='no_commercials',commercials=0);assert input_after['EDL_exists']
    if f._comskip_ini is not None:expected_cp['ini_path']=f._comskip_ini
    assert cp==expected_cp
    assert after=={**before,'custom_properties':{**before['custom_properties'],'comskip':expected_cp}}
    assert statuses==[{'success':True,'type':'comskip_status','status':'started','recording_id':ident,'title':'Owned manual Comskip input'},end]
   else:assert before==after and not statuses
   cell.update(status='passed',actual_result=result['result'],actual_task=task)
  except Exception as error:
   cell.update(status='failed',failure_type=type(error).__name__);(private/(label+'-failure.txt')).write_text(traceback.format_exc()[-8192:])
  finally:
   if observer is not None:
    try:save(private/(label+'-failed-observer-final.json'),journal.producer_observer_stop(f,observer));observer=None
    except Exception as error:report['observer_cleanup_failure']=type(error).__name__
   save(out/'report.json',report)
  if observer is not None:raise RuntimeError('ComskipObserverRetirementUnproven')
 try:
  invoke('no-file',f._comskip_rows['no_file'],{'no_file'})
  invoke('real-manual-mark',f._comskip_rows['real'],{'ok','no_commercials'})
  invoke('actual-repeat-already-processed',f._comskip_rows['real'],{'already_processed'})
 finally:
  if observer is not None:
   try:save(private/'failed-observer-final.json',journal.producer_observer_stop(f,observer))
   except Exception as error:report['observer_cleanup_failure']=type(error).__name__
 report['status']='passed'if len(report['cases'])==3 and all(c['status']=='passed'for c in report['cases'])and not report.get('observer_cleanup_failure')else'failed'
 if report['status']=='passed':
  projection={'scope':'manual completed imported local MKV; actual exit1 no_commercials only','cases':[]}
  for cell in report['cases']:
   label=cell['name'];actual=json.loads((private/(label+'-observations.json')).read_text());backend=json.loads((private/(label+'-backend.json')).read_text());api=json.loads((private/(label+'-HTTP.json')).read_text());ident=actual['before']['id'];api['path']=re.sub(r'/recordings/[0-9]+/','/recordings/<owned-recording>/',api['path'])
   props=[]
   for when in('before','after'):
    cp=actual[when]['custom_properties'];props.append({**cp,'file_path':'<owned-input>'}if'file_path'in cp else cp)
   events=[v['data']for v in actual['events']['events']if isinstance(v.get('data'),dict)and v['data'].get('type')=='comskip_status'and v['data'].get('recording_id')==ident]
   projection['cases'].append({'name':label,'HTTP':api,'backend':{k:backend[k]for k in['status','result','traceback','children']},'properties_before':props[0],'properties_after':props[1],'media_before':actual['media_before'],'media_after':actual['media_after'],'updates':[dict(v,recording_id='<owned-recording>')for v in events]})
  save(private/'actual-semantic-contract.json',projection)
  if f.backend=='Native':
   expected=json.loads(Path(f.binding['retained_source_comskip']['contract']['path']).read_text());report['exact_retained_Source_semantics_equal']=projection==expected
   if projection!=expected:report['status']='failed';report['semantic_failure']='RetainedSourceComskipContractMismatch'
 save(out/'report.json',report);return report
